F = "/content/gwps.h5ad"
if not os.path.exists(F) or os.path.getsize(F) != 8805466154:
    subprocess.run(["wget", "-q", "-O", F, "https://zenodo.org/records/7041849/files/ReplogleWeissman2022_K562_gwps.h5ad?download=1"], check=True)
h = h5py.File(F, "r")
def cat(g):
    g = h["obs"][g]; return g["categories"][:].astype(str)[g["codes"][:]]
pert = cat("perturbation"); umi = h["obs"]["UMI_count"][:]; nperts = h["obs"]["nperts"][:]
vn = h["var"]["gene_name"]; vn = vn["categories"][:].astype(str)[vn["codes"][:]] if isinstance(vn, h5py.Group) else vn[:].astype(str)
col = {g: i for i, g in enumerate(vn)}
genes = [g for g in GENES if g in col]
rng = np.random.default_rng(0); sel = []
for g in genes:
    idx = np.flatnonzero((pert == g) & (nperts <= 1)); sel.append(rng.choice(idx, min(100, len(idx)), replace=False))
ci = np.flatnonzero(pert == "control"); sel.append(rng.choice(ci, min(10000, len(ci)), replace=False))
rows = np.sort(np.concatenate(sel)); cols = np.array(sorted(col[g] for g in genes)); names = [vn[c] for c in cols]
X = h["X"]; rb = X.chunks[0]; out = np.empty((len(rows), len(cols)), np.float32); pos = 0
for b in np.unique(rows // rb):
    r = rows[(rows >= b * rb) & (rows < (b + 1) * rb)]; blk = X[b * rb:min((b + 1) * rb, X.shape[0]), :]
    out[pos:pos + len(r)] = blk[np.ix_(r - b * rb, cols)]; pos += len(r)
out = np.log1p(out / np.maximum(umi[rows][:, None], 1) * 1e4)
lab = np.where(pert[rows] == "control", "non-targeting", pert[rows])
print("panel", out.shape, "check sum", round(float(out.sum()), 2), flush=True)
from sdcd.models import SDCD
from sdcd.utils import create_intervention_dataset
Xs = (out - out.mean(0)) / (out.std(0) + 1e-9)
df = pd.DataFrame(Xs, columns=names); df["perturbation_label"] = lab
ds = create_intervention_dataset(df, perturbation_colname="perturbation_label")
t = time.time(); m = SDCD()
m.train(ds, finetune=True, device="cuda" if torch.cuda.is_available() else "cpu",
        stage1_kwargs={"n_epochs": 600, "batch_size": 512}, stage2_kwargs={"n_epochs": 600, "batch_size": 512})
W = np.abs(m.get_adjacency_matrix(threshold=False)); np.fill_diagonal(W, 0)
np.save("/content/W_sdcd_gwps_p788.npy", W)
idx = np.argsort(W.ravel())[::-1][:1500]
print("SDCD seconds", round(time.time() - t), "nonzero", int((W > 0).sum()))
print("EDGES_BEGIN")
print(";".join(f"{names[i // len(names)]},{names[i % len(names)]},{W.ravel()[i]:.4g}" for i in idx))
print("EDGES_END")
